# analyze candidate periods and orientations from test/demo seed constraints, manually encode test nonzero cells
cells=[]
# tracks represented directly as coordinates per test description: color 5 r0..16 c=r+9; color4 r2..25 c=r-2; color3 double r8..25 c=r-8 and r9..25 c=r-8+1
for r in range(17): cells.append((r,r+9,5))
for r in range(2,26): cells.append((r,r-2,4))
for r in range(8,26): cells.append((r,r-8,3))
for r in range(9,26): cells.append((r,r-7,3))
for orient in ('sum','diff'):
    ok=[]
    for p in range(1,27):
        vals={}; valid=True
        for r,c,v in cells:
            k=((r+c) if orient=='sum' else (c-r))%p
            if k in vals and vals[k]!=v: valid=False; break
            vals[k]=v
        if valid: ok.append((p,vals))
    print(orient, [p for p,v in ok])

